import math
import sys

class Vec:
    EPS = 1e-9

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, o):
        return Vec(self.x + o.x, self.y + o.y)

    def sub(self, o):
        return Vec(self.x - o.x, self.y - o.y)

    def scale(self, s):
        return Vec(self.x * s, self.y * s)

    def dot(self, o):
        return self.x * o.x + self.y * o.y

    def cross(self, o):
        return self.x * o.y - self.y * o.x

    def mag2(self):
        return self.dot(self)

    def mag(self):
        return math.sqrt(self.mag2())

    def unit(self):
        m = self.mag()
        if m == 0:
            return Vec(0, 0)
        return self.scale(1 / m)

    def rot90(self):
        return Vec(-self.y, self.x)

    def rot270(self):
        return Vec(self.y, -self.x)

    def __eq__(self, o):
        if not isinstance(o, Vec):
            return False
        return self.eq(self.x, o.x) and self.eq(self.y, o.y)

    def __str__(self):
        return f"({self.x:.2f}, {self.y:.2f})"

    @staticmethod
    def eq(a, b):
        return abs(a - b) < Vec.EPS


class Circle:
    def __init__(self, c, r):
        self.center = c
        self.radius = r

    def intersect(self, o):
        if self.center == o.center:
            return None
        dir = o.center.sub(self.center)
        d2 = dir.mag2()
        d = math.sqrt(d2)
        if self.radius + o.radius < d or self.radius + d < o.radius or o.radius + d < self.radius:
            return None
        if Vec.eq(self.radius + o.radius, d) or Vec.eq(o.radius + d, self.radius):
            return [self.center.add(dir.scale(self.radius / d))]
        if Vec.eq(self.radius + d, o.radius):
            return [self.center.sub(dir.scale(self.radius / d))]
        d1 = (self.radius * self.radius + d2 - o.radius * o.radius) / (2 * d)
        h = math.sqrt(max(0, self.radius * self.radius - d1 * d1))
        unitDir = dir.unit()
        rInt = self.center.add(unitDir.scale(d1).add(unitDir.rot270().scale(h)))
        lInt = self.center.add(unitDir.scale(d1).add(unitDir.rot90().scale(h)))
        return [rInt, lInt]


def main():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    circles = []
    for i in range(n):
        parts = input[i + 1].split()
        c = Vec(float(parts[0]), float(parts[1]))
        r = float(parts[2])
        circles.append(Circle(c, r))
    points = []
    parent = list(range(n))
    result = 1
    for i in range(n):
        newPoints = []
        for j in range(n):
            if i == j:
                continue
            intersections = circles[i].intersect(circles[j])
            if intersections is None:
                continue
            a = parent[i]
            b = parent[j]
            parent[a] = parent[parent[a]]
            parent[b] = parent[parent[b]]
            parent[a] = b
            for v in intersections:
                exists = False
                for e in newPoints:
                    if v == e:
                        exists = True
                        break
                if not exists:
                    newPoints.append(v)
        result += len(newPoints)
        for v in newPoints:
            if any(v == e for e in points):
                continue
            points.append(v)
    result -= len(points)
    for i in range(n):
        result += 1 - int(abs(i - parent[i]) / (abs(i - parent[i]) + 1e-9))
    print(result)

if __name__ == "__main__":
    main()

